LIMITS = Limits()


def read(data: bytes, name: str, limits: Limits = LIMITS, **kw: bool):
    return readers.read_object(data, name, limits, Deadline(30.0), **kw)


def by_locator(result, **want):
    return [s for s in result.spans if all(s.locator.get(k) == v for k, v in want.items())]


